import * as THREE from 'three/webgpu';
import { texture as tslTexture, add, mul, vUv, noise } from 'three/tsl';

export default function createNode(config, ctx) {
  const geometry = new THREE.PlaneGeometry(1, 1);

  const imageTexture = ctx.textureLoader.load('/prism-mock/home/nodes/orb-decor.png');
  imageTexture.colorSpace = THREE.SRGBColorSpace;

  const textureNode = tslTexture(imageTexture);

  // Subtle grain effect: fine Perlin noise, scaled to 3% intensity
  const grainNode = mul(noise(mul(vUv, 20)), 0.03);

  // Composite: texture + grain overlay
  const compositeNode = add(textureNode, grainNode);

  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: compositeNode
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(-3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
  };

  mesh.userData.handlers = {};

  return mesh;
}
